import{_ as t}from"./chunks/Fixpipe_Int8_Channel_Merge.B_ZLIx0k.js";import{_ as n,o as a,a as r,b as _}from"./app.DKoEZOcr.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"矩阵计算","link":"/api/SIMD-API/tensor_api/matrix_compute/matrix_compute"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/cube_store_key_features"},{"text":"Int8 Channel Merge","link":"/api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/int8_channel_merge"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/int8_channel_merge.md","filePath":"api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/int8_channel_merge.md","outlineHeaders":[{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"}],"lastUpdated":1787967772000}'),i={name:"api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/int8_channel_merge.md"};function o(c,e,s,l,p,d){return a(),r("div",null,[...e[0]||(e[0]=[_('<div><article class="markdown-body"><h1>Int8 Channel Merge</h1><p>Channel Merge是矩阵计算结果搬出过程中的硬件自动合并能力，仅在目的格式NZ的输出场景生效，用户无需也不能通过参数手动配置。</p><p>Int8 Channel Merge：当目标数据类型为<code>int8_t</code>或<code>uint8_t</code>时，NZ输出自动启用该特性。硬件会将分形矩阵从16×16扩展为16×32。若输出通道数N是16的偶数倍，则N方向上每两个相邻的16×16分形矩阵合并为一个16×32分形矩阵。若N是16的奇数倍，则前N - 16个通道参与合并，最后16个通道保持16×16分形矩阵不变。针对Ascend 950PR/Ascend 950DT，<code>hifloat8_t</code>、<code>fp8_e4m3fn_t</code>类型也支持该特性。</p><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>Int8 Channel Merge：当目标数据类型为<code>int8_t</code>，M为32，N为48时，硬件会将N方向上前两个16×16分形矩阵合并成一个16×32分形矩阵，剩余的一个16×16分形矩阵保持不变并输出。</p><p><strong>图1</strong> Int8 Channel Merge示意图</p><p><img src="'+t+'" alt="Int8 Channel Merge示意图"></p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>Channel Merge为硬件自动使能，不能通过参数配置。</li><li>Int8 Channel Merge在NZ输出且目的类型为<code>int8_t</code>或<code>uint8_t</code>时自动启用。Ascend 950PR/Ascend 950DT上<code>hifloat8_t</code>、<code>fp8_e4m3fn_t</code> NZ输出也支持该特性。</li></ul></article></div>',1)])])}const h=n(i,[["render",o]]);export{I as __pageData,h as default};
